steps.source:
# 10 front-bed needles
# 2 securing rows
# release hook
# 6 alternating rows

# using documentation:
width = 10

with Carrier as c1:{
  in Leftward direction: {
    tuck Front_Needles[0:width:2];
  }
  in reverse direction: {
    tuck Front_Needles[0:width:2];
  }
  releasehook;
  for _ in range(6):{
    in reverse direction:{
      knit Loops;
    }
  }
}
cut c1;

